pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        vm.assume(tos.length > 0);
        Recorder rec = new Recorder();
        address target = address(rec);
        c.transfer(from, target, tos, v);
        assertTrue(rec.allCalldataMatch());
    }
}

contract Recorder {
    uint256 public count;
    bool public mismatch;

    fallback() external payable {
        count++;
        if (msg.data.length != 100) {
            mismatch = true;
        } else {
            bytes4 sel = bytes4(msg.data[0]) | (bytes4(msg.data[1]) >> 8) | (bytes4(msg.data[2]) >> 16) | (bytes4(msg.data[3]) >> 24);
            if (sel != bytes4(keccak256("transferFrom(address,address,uint256)"))) {
                mismatch = true;
            }
        }
    }

    function allCalldataMatch() external view returns (bool) {
        return count > 0 && !mismatch;
    }
}
